#!/bin/bash
# Push items
sed -i '/"stockQuantity" to it.stockQuantity/a\                            "barcode" to it.barcode,\n                            "category" to it.category,\n                            "brand" to it.brand,\n                            "wholesalePrice" to it.wholesalePrice,\n                            "taxRate" to it.taxRate,\n                            "imageUri" to it.imageUri,\n                            "expiryDate" to it.expiryDate,\n                            "batchNumber" to it.batchNumber,\n                            "status" to it.status' app/src/main/java/com/example/data/firebase/FirebaseSyncManager.kt

# Pull items
sed -i '/val stockQuantity = doc.getDouble("stockQuantity") ?: 0.0/a\                val barcode = doc.getString("barcode") ?: ""\n                val category = doc.getString("category") ?: ""\n                val brand = doc.getString("brand") ?: ""\n                val wholesalePrice = doc.getDouble("wholesalePrice") ?: 0.0\n                val taxRate = doc.getDouble("taxRate") ?: 0.0\n                val imageUri = doc.getString("imageUri")\n                val expiryDate = doc.getLong("expiryDate")\n                val batchNumber = doc.getString("batchNumber") ?: ""\n                val status = doc.getString("status") ?: "ACTIVE"' app/src/main/java/com/example/data/firebase/FirebaseSyncManager.kt

sed -i '/stockQuantity = stockQuantity/a\                    barcode = barcode,\n                    category = category,\n                    brand = brand,\n                    wholesalePrice = wholesalePrice,\n                    taxRate = taxRate,\n                    imageUri = imageUri,\n                    expiryDate = expiryDate,\n                    batchNumber = batchNumber,\n                    status = status' app/src/main/java/com/example/data/firebase/FirebaseSyncManager.kt
